item.aggregated_output:
	web := ResolveWebAssets(webRoot)
	if logger == nil {
		logger = slog.Default()
	}
	return &Server{
		store: st,
		vault: vault,
		log:   logger,
		build: build,
		httpClient: &http.Client{Transport: &http.Transport{
			DialContext:           (&net.Dialer{Timeout: 10 * time.Second, KeepAlive: 30 * time.Second}).DialContext,
			ForceAttemptHTTP2:     true,
			MaxIdleConns:          100,
			IdleConnTimeout:       90 * time.Second,
			TLSHandshakeTimeout:   10 * time.Second,
			ResponseHeaderTimeout: 60 * time.Second,
		}, CheckRedirect: func(_ *http.Request, _ []*http.Request) error {
			return errOutboundRedirect
		}},
		webFS:     web.FS,
		webOrigin: web.Origin,
		limiter:   newLoginLimiter(),
		streams:   make(map[string]int),
		aiActive:  make(map[string]int),
	}
}

func (s *Server) acquireAIRequest(actorID string) bool {
	s.aiMu.Lock()
	defer s.aiMu.Unlock()
	if actorID == "" || s.aiActive[actorID] >= 2 || s.aiTotal >= 32 {
		return false
	}
	s.aiActive[actorID]++
	s.aiTotal++
	return true
}

func (s *Server) releaseAIRequest(actorID string) {
	s.aiMu.Lock()
	defer s.aiMu.Unlock()
	if s.aiActive[actorID] <= 0 {
		return
	}
	s.aiActive[actorID]--
	s.aiTotal--
	if s.aiActive[actorID] == 0 {
		delete(s.aiActive, actorID)
	}
}

// logStreamPageSize bounds how many stored lines one poll of a log stream
// loads, so a job with a very long log does not have to be held in memory to be
// streamed. Both log streams read it.
const logStreamPageSize = 500

func (s *Server) acquireLogStream(actorID string) bool {
	s.streamMu.Lock()
	defer s.streamMu.Unlock()
	if actorID == "" || s.streams[actorID] >= 3 || s.streamTotal >= 64 {
		return false
	}
	s.streams[actorID]++
	s.streamTotal++
	return true
}

func (s *Server) releaseLogStream(actorID string) {
	s.streamMu.Lock()
	defer s.streamMu.Unlock()
	if s.streams[actorID] <= 0 {
		return
	}
	s.streams[actorID]--
	s.streamTotal--
	if s.streams[actorID] == 0 {
		delete(s.streams, actorID)
	}
}

func (s *Server) Handler() http.Handler {
package server

import (
