	after, _ := strconv.ParseInt(r.URL.Query().Get("after"), 10, 64)
	limit := maxSimpleLogPage
	if requested, err := strconv.Atoi(r.URL.Query().Get("limit")); err == nil && requested > 0 && requested < limit {
		limit = requested
